    demos = json.load(f)

input_grid = demos[0]["input"]
output_grid = demos[0]["output"]

# Count zero neighbors (up, down, left, right)
def count_zero_neighbors(r, c, grid):
    count = 0
    h, w = len(grid), len(grid[0])
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < h and 0 <= nc < w:
            if grid[nr][nc] == 0:
                count += 1
    return count

